INSERT INTO medical_record (
    register_id, chief_complaint, present_illness, present_treatment, past_history,
    allergy_history, physical_examination, examination_proposal, precaution, diagnosis, treatment_plan
) VALUES (
    #{registrationId}, #{chiefComplaint}, #{presentIllness}, #{presentTreatment}, #{pastHistory},
    #{allergyHistory}, #{physicalExamination}, #{examinationProposal}, #{precaution}, #{diagnosis}, #{treatmentPlan}
)
